import { test, expect } from '@playwright/test';

test.describe('Catalogue Navigation - The Internet Herokuapp', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/');
  });

  test('should navigate from home page to example page and back successfully', async ({ page }) => {
    // Verify home page heading
    const welcomeHeading = page.getByRole('heading', { name: /Welcome to the Internet/i });
    await expect(welcomeHeading).toBeVisible();

    // Verify home page available examples heading
    const availableExamplesHeading = page.getByRole('heading', { name: /Available Examples/i });
    await expect(availableExamplesHeading).toBeVisible();

    // Click on A/B Testing link
    const abTestLink = page.getByRole('link', { name: /A/i });
    await abTestLink.click();

    // Verify navigation to A/B Testing page
    await expect(page).toHaveURL(/abtest/);

    // Verify A/B Testing page heading
    const abTestHeading = page.getByRole('heading', { name: /A/i });
    await expect(abTestHeading).toBeVisible();

    // Verify A/B Testing page content
    const abTestContent = page.getByText(/A/i);
    await expect(abTestContent).toBeVisible();

    // Navigate back to home page
    await page.goBack();

    // Verify return to home page
    await expect(page).toHaveURL(/index.html/);

    // Verify home page heading is visible again
    await expect(welcomeHeading).toBeVisible();
  });

  test('should handle navigation when example page does not exist', async ({ page }) => {
    // Verify home page heading
    const welcomeHeading = page.getByRole('heading', { name: /Welcome to the Internet/i });
    await expect(welcomeHeading).toBeVisible();

    // Attempt to click on a non-existent example link
    const nonExistentLink = page.getByRole('link', { name: /non-existent-page/i });

    // Verify link does not exist before clicking
    const linkExists = await nonExistentLink.isVisible();
    expect(linkExists).toBe(false);

    // Verify no navigation occurs
    const initialUrl = page.url();

    // Attempt to click the non-existent link (should fail gracefully)
    try {
      await nonExistentLink.click();
    } catch (error) {
      // Expected error when clicking non-existent element
    }

    // Verify we are still on the home page
    await expect(page).toHaveURL(/index.html/);
    await expect(welcomeHeading).toBeVisible();

    // Verify available examples heading is still visible
    await expect(availableExamplesHeading).toBeVisible();
  });
});
